import sympy as s
from calibration_bank import LEVELS,L
M=s.Matrix
k,h,t=s.symbols('k h t',real=True)
PATHS={'identity-operations':'MAT.identity.identity','figure-images':'MAT.transformation.map','vector-line-equation':'VEC.line.vector','parallelogram-area':'VEC.area-volume.parallelogram'}
RATIONALES={
'identity-operations':['Recall scalar multiplicative identity.','Distinguish identity multiplication from addition and check order.','Apply left and right identities in a matrix expression.','Recover dimensions of rectangular identity factors.','Recover an unknown entry by enforcing an inverse identity.','Classify all parameters for an involutory matrix, proving both directions.'],
'figure-images':['Apply a coordinate scaling.','Distinguish column images from row images.','Map a point with a matrix.','Map an entire triangle and derive an image edge equation.','Recover a missing original vertex from its image and check the figure.','Classify a parameter-dependent image line, including point collapse.'],
'vector-line-equation':['Find displacement between points.','Explain non-uniqueness of equivalent parameterisations.','Form a line from two points.','Find coordinate-plane intersection from a line equation.','Recover a parameter from membership of a prescribed point.','Classify existence and uniqueness of lines satisfying point and perpendicularity constraints.'],
'parallelogram-area':['Recall rectangle area.','Distinguish signed cross product and unsigned area.','Calculate area from two edge vectors.','Recover fourth vertex and area from three adjacent vertices.','Solve inverse area with both signs and verify.','Prove minimum area and classify all prescribed-area solutions.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a=v+1;b=v+3;c=v+4
 if path=='identity-operations':
  A=M([[a,1],[b,c]]);I=s.eye(2)
